I agree with @suyundukov, and would like to add that the change calculates `http` unnecessarily if `xhr` already evaluates to true.

A better approach would be:

```js
// For browsers use XHR adapter
var xhr = typeof XMLHttpRequest !== 'undefined';

if (xhr) {
  return require('./adapters/xhr');
}

// For node use HTTP adapter
var http = typeof process !== 'undefined' && Object.prototype.toString.call(process) === '[object process]';

if (http) {
  return require('./adapters/http');
}

return;

